import{_ as l,C as s,o as n,c as t,j as i,E as o,a as e,a3 as d}from"./chunks/framework.C6R8kWFE.js";const b=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/8-sinf-cs/"},"n":2,"bob":"I-bob · Kompyuter savodxonligi va arxitekturasi","lessons":[{"g":4,"title":"Kompyuterning asosiy va qo'shimcha qurilmalari","lead":"Tizim bloki, monitor va klaviatura kompyuterning faqat «skeleti» xolos. Unga ulangan o'nlab qo'shimcha qurilmalar — printerlar, skanerlar, proyektorlar va drayverlar kompyuterni haqiqiy mo'jizaviy studiyaga aylantiradi. Ushbu darsda kompyuterning barcha a'zolari va ularni xavfsiz ulash sirlarini o'rganamiz.","link":"/8-sinf-cs/hafta-02/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-1-test.html"},{"g":5,"title":"Internet, brauzerlar va elektron pochta bilan ishlash","lead":"Global tarmoq sirlari, brauzerlar anatomiyasi, Google'da professional qidiruv usullari hamda elektron pochtada xavfsiz va samarali ishlash madaniyati.","link":"/8-sinf-cs/hafta-02/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-2-test.html"},{"g":6,"title":"Kompyuter xavfsizligi va antivirus dasturlari","lead":"Kompyuterni kiberxatarlardan himoyalash, zararli dasturlar turlari, antiviruslarning ishlash sirlari hamda mustahkam parollar yaratish madaniyati.","link":"/8-sinf-cs/hafta-02/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"8-sinf-cs/hafta-02/index.md","filePath":"8-sinf-cs/hafta-02/index.md"}`),h={name:"8-sinf-cs/hafta-02/index.md"},u={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function m(c,a,y,p,f,k){const r=s("Icon");return n(),t("div",null,[i("div",u,[i("h2",g,[o(r,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi.</p><h3 id="_4-dars-uchun-kompyuterning-asosiy-va-qo-shimcha-qurilmalari" tabindex="-1">4-dars uchun (Kompyuterning asosiy va qo‘shimcha qurilmalari) <a class="header-anchor" href="#_4-dars-uchun-kompyuterning-asosiy-va-qo-shimcha-qurilmalari" aria-label="Permalink to &quot;4-dars uchun (Kompyuterning asosiy va qo‘shimcha qurilmalari)&quot;">​</a></h3><p><strong>1-topshiriq: «Periferiya qurilmalari va portlar xaritasi»</strong></p><ol><li>O&#39;zingiz yoki uyingizdagi kompyuterda mavjud bo&#39;lgan barcha portlarni (USB Type-A, Type-C, HDMI, Audio jack, RJ-45) sanab, har biriga qanday qurilma ulanganini daftaringizga yozing.</li><li><code>Win + X</code> tugmalari orqali <code>Device Manager</code>ni oching. «Display adapters» (Videokarta) va «Keyboards» (Klaviatura) bo&#39;limlarini ochib, qurilmalaringizning aniq ishlab chiqaruvchi modelini ko&#39;chiring.</li><li>Fleshkani kompyuterga ulab, vazifalar panelidagi o&#39;ng burchakdan «Safely Remove Hardware and Eject Media» amali orqali uni xavfsiz sug&#39;urish amaliyotini bajaring.</li></ol><p><strong>Kutiladigan natija:</strong> Kompyuterning jismoniy portlari va Device Manager orqali apparat ta&#39;minotini tahlil qilish ko&#39;nikmasi.</p><h3 id="_5-dars-uchun-internet-brauzerlar-va-elektron-pochta-bilan-ishlash" tabindex="-1">5-dars uchun (Internet, brauzerlar va elektron pochta bilan ishlash) <a class="header-anchor" href="#_5-dars-uchun-internet-brauzerlar-va-elektron-pochta-bilan-ishlash" aria-label="Permalink to &quot;5-dars uchun (Internet, brauzerlar va elektron pochta bilan ishlash)&quot;">​</a></h3><p><strong>2-topshiriq: «Google qidiruv va professional email»</strong></p><ol><li>Brauzeringizda (Chrome yoki Edge) <code>Ctrl + Shift + O</code> orqali xatcho&#39;plar menejerini oching va «IT Darsliklari» nomli alohida xatcho&#39;p papkasini yarating.</li><li>Google qidiruvida <code>site:</code> va <code>filetype:pdf</code> operatorlaridan foydalanib, O&#39;zbekiston saytlaridan informatika yoki dasturlash bo&#39;yicha 1 ta elektron qo&#39;llanmani toping va brauzeringizga saqlang.</li><li>Shaxsiy pochtangizdan (Gmail yoki maktab pochtasi) ustozingizga xat qoralamasi tayyorlang: <ul><li>Mavzu (Subject): «8-sinf CS 2-hafta uy vazifasi - [Ismingiz]»</li><li>Matn: Rasmiy xushmuomala salomlashish, topilgan kitob nomi va xulosa.</li><li>Fayl biriktirish (Attachment): Topilgan PDF darslikni xatga biriktiring.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> Qidiruv operatorlarini to&#39;g&#39;ri qo&#39;llash va professional darajada shakllantirilgan elektron xat loyihasi.</p><h3 id="_6-dars-uchun-kompyuter-xavfsizligi-va-antivirus-dasturlari" tabindex="-1">6-dars uchun (Kompyuter xavfsizligi va antivirus dasturlari) <a class="header-anchor" href="#_6-dars-uchun-kompyuter-xavfsizligi-va-antivirus-dasturlari" aria-label="Permalink to &quot;6-dars uchun (Kompyuter xavfsizligi va antivirus dasturlari)&quot;">​</a></h3><p><strong>3-topshiriq: «Kiberxavfsizlik auditi va kuchli parol»</strong></p><ol><li>Windows Security (yoki o&#39;rnatilgan antivirus) orqali «Quick scan» (Tezkor skanerlash) o&#39;tkazing. Tekshiruv natijasini (tekshirilgan fayllar soni va aniqlangan tahdidlar yo&#39;qligini) qayd eting.</li><li>Shaxsiy akkauntingiz (Google, Telegram yoki boshqa) uchun darsda o&#39;rganilgan formula (ibora + raqam + belgi) asosida 14 belgidan iborat kuchli parol tuzing va akkauntingizda 2FA (ikki bosqichli tasdiqlash) funksiyasini yoqing.</li><li>Kompyuteringizdagi eng muhim maktab fayllari va rasmlaringizni tashqi fleshkaga yoki bulutli xotiraga (Google Drive) zaxira nusxa (backup) sifatida nusxalang.</li></ol><p><strong>Kutiladigan natija:</strong> Antivirus bilan amaliy ishlash, shaxsiy hisoblarni 2FA bilan kuchaytirish va zaxira nusxa yaratish madaniyati.</p>',13))])])}const q=l(h,[["render",m]]);export{b as __pageData,q as default};
